constexpr int kResyProgramCount = 16;

// Returns the .resy file name owning `source`, or nullptr.
inline const char* resy_program_name(const char* source) {
    for (int i = 0; i < kResyProgramCount; ++i) {
        if (kResyPrograms[i].source == source) {
            return kResyPrograms[i].file;
        }
    }
    return nullptr;
}

// Returns the entry whose identifier names a
// `const char* source = <identifier>;` selection, or nullptr. This is how
// a host build resolves which program the firmware build selected,
// without depending on the identifier naming convention.
inline const ResyProgram* resy_program_by_identifier(
    const char* identifier) {
    if (identifier == nullptr) {
        return nullptr;
    }
    for (int i = 0; i < kResyProgramCount; ++i) {
        const char* candidate = kResyPrograms[i].identifier;
        if (candidate != nullptr &&
            std::strcmp(candidate, identifier) == 0) {
            return &kResyPrograms[i];
        }
    }
    return nullptr;
}

